// ⚙️ CONFIG DES GARAGES — une entrée par garage (même id que le YAML côté serveur)
const GARAGES = {
  "garage-demo": {
    calendarId: "primary",               // ou l'ID d'un agenda dédié au garage
    timezone: "Europe/Paris",
    notifyEmail: "toi@exemple.com",      // qui reçoit les messages et rapports d'appel
    smsFrom: "+33100000000",             // numéro Twilio (ou Sender ID alphanumérique, ex. "GARAGEDEMO")
  },
  "dentiste-demo": {
    calendarId: "ID_AGENDA_CABINET@group.calendar.google.com",
    timezone: "Europe/Paris",
    notifyEmail: "toi@exemple.com",
    smsFrom: "+33100000001",
  },
};

const body = $input.first().json.body;
const g = GARAGES[body.tenant_id] || {};
const m = body.message;
return [{ json: {
  to: body.notify_email || g.notifyEmail,
  subject: `📞 Message de ${m.customer_name} – à rappeler`,
  text: `${m.customer_name} a appelé le ${new Date(m.at).toLocaleString('fr-FR', { timeZone: g.timezone || 'Europe/Paris' })}.\n\n`
      + `Objet : ${m.reason}\n\nRappeler au : ${m.callback_number || 'numéro inconnu'}\n\n— Agent vocal IA`,
} }];

// ⚙️ CONFIG DES GARAGES — une entrée par garage (même id que le YAML côté serveur)
const GARAGES = {
  "garage-demo": {
    calendarId: "primary",               // ou l'ID d'un agenda dédié au garage
    timezone: "Europe/Paris",
    notifyEmail: "toi@exemple.com",      // qui reçoit les messages et rapports d'appel
    smsFrom: "+33100000000",             // numéro Twilio (ou Sender ID alphanumérique, ex. "GARAGEDEMO")
  },
  "dentiste-demo": {
    calendarId: "ID_AGENDA_CABINET@group.calendar.google.com",
    timezone: "Europe/Paris",
    notifyEmail: "toi@exemple.com",
    smsFrom: "+33100000001",
  },
};

const body = $input.first().json.body;
const g = GARAGES[body.tenant_id] || {};
const a = body.appointment;
return [{ json: {
  to: body.notify_email || g.notifyEmail,
  subject: `${a.new_patient === true || a.new_patient === false ? '🦷' : '🔧'} Nouveau RDV : ${a.label} – ${a.customer_name}`,
  text: [
    `Nouveau rendez-vous pris par l'assistant vocal.`,
    '',
    `Quand : ${a.label}`,
    `Client : ${a.customer_name}`,
    `Téléphone : ${a.customer_phone || 'non communiqué'}`,
    a.vehicle ? `Véhicule : ${a.vehicle}${a.plate ? ' (' + a.plate + ')' : ''}` : null,
    a.new_patient === true ? 'Dossier : nouveau patient' : a.new_patient === false ? 'Dossier : déjà patient' : null,
    `Motif : ${a.service_label}`,
    `Demande : ${a.problem_description}`,
    '',
    "Le rendez-vous est déjà dans l'agenda.",
  ].filter(l => l !== null).join('\n'),
} }];

// Mail de confirmation au client (seulement s'il a donné une adresse valide)
const a = $input.first().json.body.appointment;
if (!a.customer_email) return [];
return [{ json: {
  to: a.customer_email,
  subject: `✅ Votre rendez-vous du ${a.label} est confirmé – ${a.garage_name}`,
  text: [
    `Bonjour ${a.customer_name},`,
    '',
    `Votre rendez-vous au ${a.garage_name} est confirmé :`,
    '',
    `📅 ${a.label}`,
    `${a.vehicle ? '🔧' : '🦷'} ${a.service_label}`,
    a.vehicle ? `🚗 ${a.vehicle}${a.plate ? ' (' + a.plate + ')' : ''}` : null,
    `📍 ${a.garage_address}`,
    '',
    `Pour modifier ou annuler, il suffit de nous rappeler${a.vehicle ? '' : ' au moins 24 heures avant'}.`,
    '',
    'À bientôt,',
    `L'équipe du ${a.garage_name}`,
  ].filter(l => l !== null).join('\n'),
} }];

// ⚙️ CONFIG DES GARAGES — une entrée par garage (même id que le YAML côté serveur)
const GARAGES = {
  "garage-demo": {
    calendarId: "primary",               // ou l'ID d'un agenda dédié au garage
    timezone: "Europe/Paris",
    notifyEmail: "toi@exemple.com",      // qui reçoit les messages et rapports d'appel
    smsFrom: "+33100000000",             // numéro Twilio (ou Sender ID alphanumérique, ex. "GARAGEDEMO")
  },
  "dentiste-demo": {
    calendarId: "ID_AGENDA_CABINET@group.calendar.google.com",
    timezone: "Europe/Paris",
    notifyEmail: "toi@exemple.com",
    smsFrom: "+33100000001",
  },
};

const body = $input.first().json.body;
const g = GARAGES[body.tenant_id] || {};
const r = body.report;
const labels = { rdv_pris: '✅ RDV pris', message: '📝 Message laissé', transfert: '↪️ Transféré', sans_suite: '⚪ Sans suite' };
const rdv = (r.appointments || []).map(a => {
  const who = [
    a.customer_name,
    a.vehicle ? `${a.vehicle}${a.plate ? ' (' + a.plate + ')' : ''}` : '',
    a.new_patient === true ? 'nouveau patient' : a.new_patient === false ? 'déjà patient' : '',
  ].filter(Boolean).join(', ');
  return `- ${a.label} : ${a.service_label}, ${who}\n  ${a.problem_description}`;
}).join('\n');
const msgs = (r.messages || []).map(m => `- ${m.customer_name} : ${m.reason} (rappel ${m.callback_number})`).join('\n');
const transcript = (r.transcript || []).map(t => `${t.role === 'agent' ? 'Agent' : 'Client'} : ${t.text}`).join('\n');
return [{ json: {
  to: body.notify_email || g.notifyEmail,
  outcome: r.outcome,
  subject: `${labels[r.outcome] || r.outcome} – appel de ${r.caller_number || 'numéro masqué'} (${Math.round(r.duration_s / 60 * 10) / 10} min)`,
  text: [
    rdv && `RENDEZ-VOUS\n${rdv}`,
    msgs && `MESSAGES\n${msgs}`,
    `TRANSCRIPTION\n${transcript}`,
  ].filter(Boolean).join('\n\n'),
} }];
